package com.aster.vpn;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
public class ProfilesTest {
 private final String id="f1f1408b-959e-4c09-bb5b-981c8ba33101";
 private String uri(String query){return "vless://"+id+"@example.com:443?"+query+"#%F0%9F%87%B7%F0%9F%87%BA%20Test";}
 @Test public void nullXhttpExtra()throws Exception{JSONObject p=Profiles.parse(uri("type=xhttp&security=tls&extra=null")).getJSONObject(0);assertEquals("🇷🇺 Test",p.getString("name"));assertFalse(p.getJSONObject("outbound").getJSONObject("streamSettings").getJSONObject("xhttpSettings").has("extra"));}
 @Test public void rawTransport()throws Exception{assertEquals("raw",Profiles.parse(uri("type=raw&security=reality&pbk=test&sid=ab")).getJSONObject(0).getJSONObject("outbound").getJSONObject("streamSettings").getString("network"));}
 @Test public void base64List()throws Exception{String text=uri("type=ws&security=tls")+"\n"+uri("type=xhttp&extra=null");assertEquals(2,Profiles.parse(Base64.getEncoder().encodeToString(text.getBytes(StandardCharsets.UTF_8))).length());}
 @Test(expected=IllegalArgumentException.class)public void unsafeTls()throws Exception{Profiles.parse(uri("security=tls&allowInsecure=1"));}
 @Test(expected=IllegalArgumentException.class)public void unsupportedTransport()throws Exception{Profiles.parse(uri("type=unknown"));}
 @Test(expected=IllegalArgumentException.class)public void arrayExtra()throws Exception{Profiles.parse(uri("type=xhttp&extra=%5B%5D"));}
 @Test public void identityStable()throws Exception{String link=uri("type=raw");assertEquals(Profiles.parse(link).getJSONObject(0).getString("id"),Profiles.parse(link).getJSONObject(0).getString("id"));}
 @Test public void tunNotSocksBridge()throws Exception{JSONObject p=Profiles.parse(uri("type=xhttp&security=tls")).getJSONObject(0);JSONObject c=new JSONObject(XraySettings.build(p,new JSONObject()));assertEquals("tun",c.getJSONArray("inbounds").getJSONObject(0).getString("protocol"));assertFalse(c.getJSONArray("outbounds").getJSONObject(0).has("mux"));}
 @Test public void providerMuxPreserved()throws Exception{JSONObject p=Profiles.parse(uri("type=xhttp&security=tls")).getJSONObject(0);p.getJSONObject("outbound").put("mux",new JSONObject().put("enabled",false));JSONObject c=new JSONObject(XraySettings.build(p,new JSONObject()));assertFalse(c.getJSONArray("outbounds").getJSONObject(0).getJSONObject("mux").getBoolean("enabled"));}
 @Test public void lastConnectionSurvivesProcessRestart()throws Exception{JSONObject saved=new JSONObject().put("id","last").put("name","Last server");JSONObject data=new JSONObject(new JSONObject().put("lastConnection",saved).toString());assertEquals("last",Store.connection(data,true).getString("id"));}
 @Test public void tileFallsBackToSelectionBeforeFirstConnection()throws Exception{JSONObject p=new JSONObject().put("id","selected");JSONObject data=new JSONObject().put("selected","selected").put("subscriptions",new JSONArray().put(new JSONObject().put("servers",new JSONArray().put(p))));assertEquals("selected",Store.connection(data,true).getString("id"));}
 @Test public void tileWithoutAnyServerOpensSetup()throws Exception{assertNull(Store.connection(new JSONObject(),true));}
 @Test public void lastConnectionUsesCurrentProfileWithSameId()throws Exception{JSONObject saved=new JSONObject().put("id","last").put("name","Old"),fresh=new JSONObject().put("id","last").put("name","Updated");JSONObject data=new JSONObject().put("lastConnection",saved).put("subscriptions",new JSONArray().put(new JSONObject().put("servers",new JSONArray().put(fresh))));assertEquals("Updated",Store.connection(data,true).getString("name"));}
 private String awg(){String key=Base64.getEncoder().encodeToString(new byte[32]);return "[Interface]\nPrivateKey="+key+"\nAddress=10.8.0.2/32\nJc=4\nH1=100-200\n[Peer]\nPublicKey="+key+"\nEndpoint=192.0.2.1:1234\nAllowedIPs=0.0.0.0/0, ::/0\nPersistentKeepalive=25";}
 @Test public void awgUapi()throws Exception{AwgConfig c=AwgConfig.parse(awg());assertTrue(c.uapi.contains("jc=4\n"));assertTrue(c.uapi.indexOf("public_key=")<c.uapi.indexOf("replace_allowed_ips="));assertTrue(c.uapi.contains("endpoint=192.0.2.1:1234"));assertEquals("10.8.0.2/32",c.addresses.get(0));}
 @Test public void awg31Parameters()throws Exception{String key=Base64.getEncoder().encodeToString(new byte[32]);String raw=awg().replace("Jc=4","Jc=4\nHeaderProtectionKey="+key+"\nContentPaddingAddition=16-64\nRekeyAfterTime=120-180\nRekeyTimeout=4-8\nRejectAfterTime=200-300\nKeepaliveTimeout=10-20\nMaxHandshakeAttempts=10-20\nRandomTrailers=on\nDisableCookies=0");String uapi=AwgConfig.parse(raw).uapi;assertTrue(uapi.contains("header_protection_key="+"0".repeat(64)+"\n"));for(String setting:new String[]{"content_padding_addition=16-64","rekey_after_time=120-180","rekey_timeout=4-8","reject_after_time=200-300","keepalive_timeout=10-20","max_handshake_attempts=10-20","random_trailers=true","disable_cookies=false"})assertTrue(setting,uapi.contains(setting+"\n"));}
 @Test public void awgDeviceSectionAndHexKeys()throws Exception{String raw=awg().replace("Jc=4","[Device]\nHeaderProtectionKey="+"a".repeat(64));assertTrue(AwgConfig.parse(raw).uapi.contains("header_protection_key="+"a".repeat(64)));}
 @Test public void awgPeerFieldOrderIndependent()throws Exception{String raw=awg().replace("[Peer]\nPublicKey=","[Peer]\nPersistentKeepalive=25\nPublicKey=");String uapi=AwgConfig.parse(raw).uapi;assertTrue(uapi.indexOf("public_key=")<uapi.indexOf("persistent_keepalive_interval="));}
 @Test(expected=IllegalArgumentException.class)public void awgMultiplePeersRejected()throws Exception{AwgConfig.parse(awg()+"\n[Peer]\nPublicKey="+Base64.getEncoder().encodeToString(new byte[32]));}
 @Test public void xudpKeyIs32BytesBase64Url()throws Exception{String hwid="00000000-0000-0000-0000-000000000000";String key=Identity.xudpKey(hwid);assertEquals(32,Base64.getUrlDecoder().decode(key).length);assertEquals(43,key.length());assertEquals(key,Identity.xudpKey(hwid));assertNotEquals(key,Identity.xudpKey("another-device"));}
 @Test public void mixedAwg()throws Exception{String link="vpn://"+Base64.getEncoder().encodeToString(awg().getBytes(StandardCharsets.UTF_8));assertEquals(2,Profiles.parse(uri("type=raw")+"\n"+link).length());}
 @Test(expected=IllegalArgumentException.class)public void awgHooksRejected()throws Exception{AwgConfig.parse(awg().replace("Jc=4","PostUp=bad"));}
 @Test public void lastSuccessfulNotCurrentSelection()throws Exception{JSONObject old=new JSONObject().put("id","old"),selected=new JSONObject().put("id","new");JSONObject d=new JSONObject().put("selected","new").put("lastConnection",old).put("subscriptions",new JSONArray().put(new JSONObject().put("servers",new JSONArray().put(selected))));assertEquals("old",Store.connection(d,true).getString("id"));assertEquals("new",Store.connection(d,false).getString("id"));}
 @Test public void suppliedPublicSubscription()throws Exception{Path path=Paths.get("../../tests/generated/gitverse-public.txt");if(Files.exists(path))assertEquals(144,Profiles.parse(new String(Files.readAllBytes(path),StandardCharsets.UTF_8)).length());}
}
